@staticmethod
def _to_camel_case(key):
    """
    convert key string into camel case
    :param key:str
    :return:str, converted key string
    >>> camelize_map = CamelCaseMap()
    >>> camelize_map._to_camel_case('first_name')
    'firstName'
    """
    if not isinstance(key, str):
        return key
    parts = key.split('_')
    if len(parts) == 1:
        return key.lower()
    result = parts[0].lower()
    for part in parts[1:]:
        result += part.title()
    return result
